const input = $input.first().json;

const inputMarketRaw = input.market_name;
const inputDate = input.arrival_date; // format: DD/MM/YYYY

// Normalize: APMC hatao, lowercase, extra spaces hatao
const normalize = (name) =>
  name.toLowerCase().replace(/apmc/gi, "").replace(/\s+/g, " ").trim();

const inputMarket = normalize(inputMarketRaw);

// Date se month aur years nikalo
const parts = inputDate.split("/");
const inputMonth = parts[1];           // "04"
const currentYear = parseInt(parts[2]); // 2026

const allowedYears = [
  currentYear,
  currentYear - 1,
  currentYear - 2
];

// Records all mondies node se aa rahe hain
const records = input.records;

const filtered = records.filter(item => {
  const [day, month, year] = item.Arrival_Date.split("/");

  const recordMarket = normalize(item.Market);

  // Dono taraf se check karo — APMC wala aur bina APMC wala dono match hon
  const marketMatch =
    recordMarket.includes(inputMarket) ||
    inputMarket.includes(recordMarket);

  const monthMatch = month === inputMonth;
  const yearMatch = allowedYears.includes(parseInt(year));

  return marketMatch && monthMatch && yearMatch;
});

return filtered.map(item => ({ json: item }));

// Filtered data jo pichle node se aa raha hai
const records = $input.all();

if (!records || records.length === 0) {
    return { json: { error: "No historical data found to make a prediction." } };
}

const market = records[0].json.Market || "Unknown Market";
const commodity = records[0].json.Commodity || "Unknown Commodity";

let totalModalPrice = 0;
let maxPrice = -Infinity;
let minPrice = Infinity;
let recentPrices = [];

records.forEach(r => {
    const price = Number(r.json.Modal_Price); 

    if (price && !isNaN(price)) {
        totalModalPrice += price;
        if (price > maxPrice) maxPrice = price;
        if (price < minPrice) minPrice = price;
    }

    // Recent trend ke liye pichle kuch records (max 7) save kar lete hain
    if(recentPrices.length < 7) {
        // String ki jagah directly JSON object pass kar rahe hain
        recentPrices.push({
            date: r.json.Arrival_Date,
            price: price
        });
    }
});

const avgPrice = totalModalPrice / records.length;

// Sirf calculated values return kar rahe hain, koi prompt nahi.
return { 
    json: { 
        market_name: market, 
        commodity_name: commodity,
        historical_stats: {
            average_price: parseFloat(avgPrice.toFixed(2)),
            highest_price: maxPrice === -Infinity ? null : maxPrice,
            lowest_price: minPrice === Infinity ? null : minPrice
        },
        recent_trend: recentPrices
    } 
};

// 1. Extract the text containing the JSON array from the Gemini output
let aiResponseText = $input.first().json.content.parts[0].text;

// 2. Clean up any markdown formatting (like ```json or ```) just in case
aiResponseText = aiResponseText.replace(/```json/gi, "").replace(/```/g, "").trim();

try {
    // 3. Parse the cleaned text into a Javascript Array (JSON)
    const parsedData = JSON.parse(aiResponseText);

    // 4. Return the data as individual items for n8n to process
    return parsedData.map(item => ({ json: item }));

} catch (error) {
    // If parsing fails, output an error along with the raw text for debugging
    return [{
        json: {
            error: "Failed to parse AI output into JSON",
            raw_text: aiResponseText
        }
    }];
}

